591	  /**
592	   * Update an existing issue.
593	   *
594	   * Appends an update event to the issue file, recomputes state, and updates the index.
595	   * Handles hierarchy side effects: downward cascade (auto-close done children when parent
596	   * closes), upward promotion (promote parent when child advances past it), and reparenting
597	   * validation. Also auto-resolves active blockages when the issue transitions to done/closed.
598	   *
599	   * @param id - The issue ID to update
600	   * @param params - Update parameters (at least one field required besides author)
601	   * @param params.title - New title
602	   * @param params.description - New description
603	   * @param params.status - New status
604	   * @param params.assignee - New assignee, or null to clear
605	   * @param params.tags - New tags (replaces existing)
606	   * @param params.priority - New priority (1-5)
607	   * @param params.parentId - New parent ID, or null to detach
608	   * @param params.author - Override author (resolved by auth layer if not provided)
609	   * @returns `{ result: "OK" }` on success, or a AgentrackError on auth failure
610	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
611	   * @throws {AgentrackError} INVALID_PARAMS if no fields provided besides author
612	   * @throws {AgentrackError} NOT_FOUND if issue ID is not in the index
613	   * @throws {AgentrackError} ISSUE_MISSING if index entry exists but file is missing
614	   * @throws {AgentrackError} HIERARCHY_CONSTRAINT if status change violates parent/child rules
615	   *
616	   * @example
617	   * ```typescript
618	   * await tracker.update("abc123def4", { status: "in-progress", priority: 2 });
619	   * ```
620	   */
621	  async update(id: IssueId, params: UpdateParams): Promise<UpdateResult> {
622	    const trackerDir = resolveTrackerDir(this.cwd);
623	    if (!trackerDir) {
624	      throw new AgentrackError(
625	        ErrorCodes.NOT_INITIALIZED.result,
626	        "No .agentrack/ directory found. Run `agt init` first.",
627	        ErrorCodes.NOT_INITIALIZED.exitCode,
628	      );
629	    }
630	
631	    // Validate at least one field provided (besides author)
632	    const hasField =
633	      params.title !== undefined ||
634	      params.description !== undefined ||
635	      params.status !== undefined ||
636	      params.assignee !== undefined ||
637	      params.tags !== undefined ||
638	      params.priority !== undefined ||
639	      params.parentId !== undefined;
640	
641	    if (!hasField) {
642	      throw new AgentrackError(
643	        ErrorCodes.INVALID_PARAMS.result,
644	        "At least one field must be provided for update.",
645	        ErrorCodes.INVALID_PARAMS.exitCode,
646	      );
647	    }
648	
649	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
650	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
651	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
652	    if (authResult instanceof AgentrackError) return authResult;
653	    const author = params.author ?? authResult.author;
654	
655	    const index = await readIndex(trackerDir);
656	    const entry = findEntry(index, id);
657	    if (!entry) {
658	      throw new AgentrackError(
659	        ErrorCodes.NOT_FOUND.result,
660	        `Issue \`${id}\` not found in index.`,
661	        ErrorCodes.NOT_FOUND.exitCode,
662	      );
663	    }
664	
665	    const issueFilePath = join(trackerDir, entry.path);
666	    if (!existsSync(issueFilePath)) {
667	      throw new AgentrackError(
668	        ErrorCodes.ISSUE_MISSING.result,
669	        `Issue file for \`${id}\` is missing.`,
670	        ErrorCodes.ISSUE_MISSING.exitCode,
671	      );
672	    }
673	
674	    // Save old values for hierarchy handling
675	    const oldStatus = entry.status;
676	    const oldParentId = entry.parentId;
677	
678	    // ── Hierarchy validation (before any state changes) ────────────
679	
680	    // Validate downward constraints for status change
681	    if (params.status !== undefined && params.status !== oldStatus) {
682	      if (params.status === "done" || params.status === "closed") {
683	        const childIds = getChildren(index, id);
684	        const childEntries = childIds
685	          .map((cid) => findEntry(index, cid))
686	          .filter((e): e is IndexEntry => e !== null);
687	        const validationError = validateParentStatusChange(index, childEntries, params.status);
688	        if (validationError) {
689	          throw new AgentrackError(
690	            ErrorCodes.HIERARCHY_CONSTRAINT.result,
691	            validationError,
692	            ErrorCodes.HIERARCHY_CONSTRAINT.exitCode,
693	          );
694	        }
695	      }
696	    }
697	
698	    // Validate reparenting constraints
699	    if (params.parentId !== undefined && params.parentId !== oldParentId) {
700	      if (params.parentId !== null) {
701	        const newParentEntry = findEntry(index, params.parentId);
702	        if (!newParentEntry) {
703	          throw new AgentrackError(
704	            ErrorCodes.NOT_FOUND.result,
705	            `Parent issue \`${params.parentId}\` not found in index.`,
706	            ErrorCodes.NOT_FOUND.exitCode,
707	          );
708	        }
709	        const validationError = validateNewChild(newParentEntry);
710	        if (validationError) {
711	          throw new AgentrackError(
712	            ErrorCodes.HIERARCHY_CONSTRAINT.result,
713	            validationError,
714	            ErrorCodes.HIERARCHY_CONSTRAINT.exitCode,
715	          );
716	        }
717	      }
718	    }
719	
720	    // ── Build and append update event ──────────────────────────────
721	
722	    // Build update event content with only the provided fields
723	    const content: Partial<
724	      Pick<
725	        IssueProperties,
726	        "title" | "description" | "status" | "assignee" | "tags" | "priority" | "parentId"
727	      >
728	    > = {};
729	    if (params.title !== undefined) content.title = params.title;
730	    if (params.description !== undefined) content.description = params.description;
731	    if (params.status !== undefined) content.status = params.status;
732	    if (params.assignee !== undefined) content.assignee = params.assignee;
733	    if (params.tags !== undefined) content.tags = params.tags;
734	    if (params.priority !== undefined) content.priority = params.priority;
735	    if (params.parentId !== undefined) content.parentId = params.parentId;
736	
737	    const now = new Date().toISOString();
738	
739	    const updateEvent = {
740	      type: "update" as const,
741	      timestamp: now,
742	      author,
743	      content,
744	    };
745	
746	    // Append event to issue file
747	    await appendEvent(issueFilePath, updateEvent);
748	
749	    // Recompute state from all events
750	    const events = await replayEvents(issueFilePath);
751	    const computed = computeState(events, id);
752	
753	    // Update index entry with new computed values
754	    let updatedIndex = updateEntry(index, id, {
755	      title: computed.title,
756	      status: computed.status,
757	      assignee: computed.assignee,
758	      parentId: computed.parentId,
759	      tags: computed.tags,
760	      priority: computed.priority,
761	    });
762	
763	    // ── Hierarchy handling (after event append, before index write) ─
764	
765	    // 1. Handle reparenting (childrenOf updates)
766	    if (params.parentId !== undefined && params.parentId !== oldParentId) {
767	      // Detach from old parent
768	      if (oldParentId !== null) {
769	        updatedIndex = removeChild(updatedIndex, oldParentId, id);
770	      }
771	      // Attach to new parent
772	      if (params.parentId !== null) {
773	        updatedIndex = addChild(updatedIndex, params.parentId, id);
774	
775	        // Upward promotion for reparenting: if child's status is past new parent's status
776	        const newParentEntry = findEntry(updatedIndex, params.parentId);
777	        if (newParentEntry && isStatusAfter(computed.status, newParentEntry.status)) {
778	          const promotions = computeUpwardPromotions(
779	            updatedIndex,
780	            newParentEntry,
781	            computed.status,
782	            (iid) => findEntry(updatedIndex, iid),
783	          );
784	          for (const promo of promotions) {
785	            const promoEntry = findEntry(updatedIndex, promo.issueId);
786	            if (promoEntry && promo.event.type === "update" && promo.event.content.status) {
787	              await appendEvent(join(trackerDir, promoEntry.path), promo.event);
788	              updatedIndex = updateEntry(updatedIndex, promo.issueId, {
789	                status: promo.event.content.status,
790	              });
791	            }
792	          }
793	        }
794	      }
795	    }
796	
797	    // 2. Handle status change
798	    if (params.status !== undefined && params.status !== oldStatus) {
799	      // Downward cascade: auto-close done children when parent closes
800	      if (params.status === "closed") {
801	        updatedIndex = await cascadeClose(updatedIndex, id, trackerDir);
802	      }
803	
804	      // Upward promotion: promote parent if child advanced past it
805	      const currentParentId = computed.parentId;
806	      if (currentParentId) {
807	        const parentEntry = findEntry(updatedIndex, currentParentId);
808	        if (parentEntry && isStatusAfter(params.status, parentEntry.status)) {
809	          const promotions = computeUpwardPromotions(
810	            updatedIndex,
811	            parentEntry,
812	            params.status,
813	            (iid) => findEntry(updatedIndex, iid),
814	          );
815	          for (const promo of promotions) {
816	            const promoEntry = findEntry(updatedIndex, promo.issueId);
817	            if (promoEntry && promo.event.type === "update" && promo.event.content.status) {
818	              await appendEvent(join(trackerDir, promoEntry.path), promo.event);
819	              updatedIndex = updateEntry(updatedIndex, promo.issueId, {
820	                status: promo.event.content.status,
821	              });
822	            }
823	          }
824	        }
825	      }
826	    }
827	
828	    await writeIndex(trackerDir, updatedIndex);
829	
830	    // ── Auto-resolution: resolve active blockages when issue → done/closed ──
831	    if (params.status !== undefined && params.status !== oldStatus) {
832	      if (params.status === "done" || params.status === "closed") {
833	        const deps = await readDependencies(trackerDir);
834	        const activeBlocks = (deps.blocks[id] ?? []).filter((e) => e.status === "active");
835	
836	        if (activeBlocks.length > 0) {
837	          let updatedDeps = deps;
838	          for (const entry of activeBlocks) {
839	            updatedDeps = resolveBlockage(updatedDeps, entry.blockedId, entry.blockerId);
840	
841	            const blockedEntry = findEntry(updatedIndex, entry.blockedId);
842	            if (blockedEntry) {
843	              const now = new Date().toISOString();
844	              const resolveEvent: Event = {
845	                type: "blockage-resolved",
846	                timestamp: now,
847	                author: "system",
848	                content: {
849	                  blockerId: id,
850	                  reason: `Blocker issue ${id} transitioned to ${params.status}`,
851	                },
852	              };
853	              await appendEvent(join(trackerDir, blockedEntry.path), resolveEvent);
854	            }
855	          }
856	          await writeDependencies(trackerDir, updatedDeps);
857	        }
858	      }
859	    }
860	
861	    return { result: "OK" };
862	  }
